-- ---------------------------------------------------------------- hdr_pre_upgrade.sql
BEGIN
  BEGIN
    DBMS_SCHEDULER.DISABLE('HDR_TICK', force => TRUE);
    DBMS_SCHEDULER.STOP_JOB('HDR_TICK', force => FALSE);
  EXCEPTION WHEN OTHERS THEN
    IF SQLCODE NOT IN (-27475, -27476, -27366) THEN   -- no such job / not running
      RAISE;
    END IF;
  END;
  BEGIN
    EXECUTE IMMEDIATE q'[MERGE INTO HDR_SETTINGS t USING (SELECT 'maintenance' k FROM DUAL) s ON (t.SKEY = s.k)
                         WHEN MATCHED THEN UPDATE SET SVALUE = 'Y'
                         WHEN NOT MATCHED THEN INSERT (SKEY, SVALUE) VALUES (s.k, 'Y')]';
    COMMIT;
  EXCEPTION WHEN OTHERS THEN
    IF SQLCODE <> -942 THEN   -- a first install: no settings yet
      RAISE;
    END IF;
  END;
END;
/

-- ---------------------------------------------------------------- hader_interface.sql
DECLARE
  n NUMBER;
  m NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_PUNCHES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_PUNCHES (
        PUNCH_ID      NUMBER(12)     NOT NULL,          -- Hader's punch number (unique)
        EMP_CODE      VARCHAR2(30)   NOT NULL,          -- employee number on the terminal
        PUNCH_TIME    DATE           NOT NULL,
        PUNCH_STATE   NUMBER(3),                        -- 0 in, 1 out, 2 break out, 3 break in, 4 OT in, 5 OT out
        STATE_NAME    VARCHAR2(30),
        VERIFY_TYPE   VARCHAR2(30),                     -- fingerprint, face, palm, card, password...
        DEVICE_SN     VARCHAR2(50),
        DEVICE_NAME   VARCHAR2(100),
        SOURCE        VARCHAR2(10),                     -- device / tcp / manual / import
        TEMPERATURE   NUMBER(4,1),                      -- the body temperature a thermal terminal took
        UPLOADED_AT   DATE,                             -- reached the server (the terminal's clock)
        ORIG_TIME     DATE,                             -- its time before a clock fix
        FIXED_AT      DATE,
        CREATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_PUNCHES_PK PRIMARY KEY (PUNCH_ID)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_PUNCHES_EMP_IX ON HADER_PUNCHES (EMP_CODE, PUNCH_TIME)';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_PUNCHES_TIME_IX ON HADER_PUNCHES (PUNCH_TIME)';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_ATT_DAILY';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_ATT_DAILY (
        EMP_CODE      VARCHAR2(30)   NOT NULL,
        ATT_DATE      DATE           NOT NULL,          -- the day (time part 00:00)
        STATUS        VARCHAR2(20),                     -- present, late, early, late_early, absent, leave,
                                                        -- holiday, off, incomplete, unscheduled, pending
        STATUS_AR     VARCHAR2(40),
        STATUS_EN     VARCHAR2(40),
        TIMETABLE     VARCHAR2(60),
        SCHED_IN      DATE,
        SCHED_OUT     DATE,
        CLOCK_IN      DATE,
        CLOCK_OUT     DATE,
        REQUIRED_MIN  NUMBER(6),                        -- minutes the employee should have worked
        WORKED_MIN    NUMBER(6),
        LATE_MIN      NUMBER(6),
        EARLY_MIN     NUMBER(6),
        OT_MIN        NUMBER(6),
        LEAVE_MIN     NUMBER(6),
        ABSENT_DAYS   NUMBER(5,2),                      -- the day's share absent: 1 absent, less with leave or a partial absence
        ABSENT_MIN    NUMBER(6),                        -- minutes of absence
        LEAVE_CODES   VARCHAR2(100),
        HOLIDAY       VARCHAR2(100),
        PUNCHES       VARCHAR2(400),                    -- every punch of the day: 07:52 12:30 16:05
        UPDATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_ATT_DAILY_PK PRIMARY KEY (EMP_CODE, ATT_DATE)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_ATT_DAILY_DATE_IX ON HADER_ATT_DAILY (ATT_DATE, STATUS)';
  END IF;
  -- added in version 1.5: tables created by an earlier script get it in place
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_ATT_DAILY' AND column_name = 'ABSENT_MIN';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_ATT_DAILY ADD (ABSENT_MIN NUMBER(6))';
  END IF;
  -- 1.9.5: the body temperature a thermal terminal took (the punch log shows it)
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_PUNCHES' AND column_name = 'TEMPERATURE';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_PUNCHES ADD (TEMPERATURE NUMBER(4,1))';
  END IF;
  -- 2.3.7: when the punch reached the server, on the terminal's clock (the punch log's "arrived after")
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_PUNCHES' AND column_name = 'UPLOADED_AT';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_PUNCHES ADD (UPLOADED_AT DATE)';
  END IF;
  -- 2.3.8: a punch whose clock had gone back to midnight, corrected: the time the terminal gave it, and when
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_PUNCHES' AND column_name = 'ORIG_TIME';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_PUNCHES ADD (ORIG_TIME DATE, FIXED_AT DATE)';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_EMP_PHOTOS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_EMP_PHOTOS (
        EMP_CODE      VARCHAR2(30)   NOT NULL,
        PHOTO         BLOB,                             -- JPEG
        SOURCE        VARCHAR2(10),                     -- HAND / DEVICE: the card picture; CAPTURE: the recognition photo
        UPDATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_EMP_PHOTOS_PK PRIMARY KEY (EMP_CODE)
      )]';
  END IF;
  -- added in version 1.6.6: the card picture (shown by the terminals) apart from the recognition photo
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_EMP_PHOTOS' AND column_name = 'SOURCE';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_EMP_PHOTOS ADD (SOURCE VARCHAR2(10))';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_REQUESTS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_REQUESTS (
        REQ_ID        RAW(16)        DEFAULT SYS_GUID() NOT NULL,
        KIND          VARCHAR2(20)   NOT NULL,          -- SYNC, PUNCHES, EMPLOYEES, LEAVES, RECALC
        EMP_CODE      VARCHAR2(30),                     -- RECALC / SYNC: one employee only (optional)
        DATE_FROM     DATE,                             -- RECALC / SYNC / LEAVES: period (default today)
        DATE_TO       DATE,
        REQUESTED_BY  VARCHAR2(100),
        REQUESTED_AT  DATE DEFAULT SYSDATE NOT NULL,
        STATUS        VARCHAR2(10)   DEFAULT 'NEW' NOT NULL,   -- NEW, RUNNING, DONE, FAILED
        STARTED_AT    DATE,
        FINISHED_AT   DATE,
        MESSAGE       VARCHAR2(4000),
        CONSTRAINT HADER_REQUESTS_PK PRIMARY KEY (REQ_ID)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_REQUESTS_ST_IX ON HADER_REQUESTS (STATUS, REQUESTED_AT)';
  END IF;
  -- added in version 1.5.8: a request for one terminal (KIND = DEVICE)
  FOR c IN (SELECT 'DEVICE_SN' col, 'VARCHAR2(50)' def FROM DUAL                -- the terminal's serial number
            UNION ALL SELECT 'ACTION', 'VARCHAR2(30)' FROM DUAL                -- what to do (see HADER_DEVICES below)
            UNION ALL SELECT 'DETAIL', 'VARCHAR2(400)' FROM DUAL) LOOP          -- e.g. 9 face / 1 finger to enroll
    SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_REQUESTS' AND column_name = c.col;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE HADER_REQUESTS ADD (' || c.col || ' ' || c.def || ')';
    END IF;
  END LOOP;
  -- added in version 1.8.0: the employee portal of APEX app 141 asks Hader for an employee's requests, balances and
  -- inbox (KIND = PORTAL; ACTION mine / leave / manual / overtime / cancel / read; DETAIL the fields as JSON in plain
  -- ASCII, so it may be long) and Hader answers in REPLY (JSON in plain ASCII)
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_REQUESTS' AND column_name = 'REPLY';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_REQUESTS ADD (REPLY CLOB)';
  END IF;
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_REQUESTS' AND column_name = 'DETAIL'
     AND data_length < 4000;
  IF n > 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_REQUESTS MODIFY (DETAIL VARCHAR2(4000))';
  END IF;
  SELECT COUNT(*) INTO n FROM user_indexes WHERE index_name = 'HADER_REQUESTS_EMP_IX';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_REQUESTS_EMP_IX ON HADER_REQUESTS (EMP_CODE, KIND, REQUESTED_AT)';
  END IF;

  -- added in version 1.6.3, for reports that add up exactly as Hader's: the work days the day counts as,
  -- the share of them attended, the missing check-in / check-out, and the day's first and last punch
  m := 0;
  FOR c IN (SELECT 'WORKDAY' col, 'NUMBER(5,2)' def FROM DUAL UNION ALL SELECT 'PRESENT', 'NUMBER(5,2)' FROM DUAL
            UNION ALL SELECT 'MISSED_IN', 'NUMBER(2)' FROM DUAL UNION ALL SELECT 'MISSED_OUT', 'NUMBER(2)' FROM DUAL
            UNION ALL SELECT 'MISSED_LIST', 'VARCHAR2(200)' FROM DUAL UNION ALL SELECT 'FIRST_PUNCH', 'DATE' FROM DUAL
            UNION ALL SELECT 'LAST_PUNCH', 'DATE' FROM DUAL) LOOP
    SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_ATT_DAILY' AND column_name = c.col;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE HADER_ATT_DAILY ADD (' || c.col || ' ' || c.def || ')';
      m := m + 1;
    END IF;
  END LOOP;
  IF m > 0 THEN   -- the days already there get them on their next calculation: this month and the last one now
    EXECUTE IMMEDIATE q'[INSERT INTO HADER_REQUESTS (KIND, DATE_FROM, DATE_TO, REQUESTED_BY)
                         VALUES ('RECALC', ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1), TRUNC(SYSDATE), 'install 1.6.3')]';
  END IF;

  -- the terminals, as Hader sees them (written every minute while APEX requests are on)
  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_DEVICES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_DEVICES (
        SN            VARCHAR2(50)   NOT NULL,
        NAME          VARCHAR2(100),
        AREA_NAME     VARCHAR2(100),
        IP            VARCHAR2(50),
        STATE         VARCHAR2(10),                     -- online, offline, disabled
        MODE_NAME     VARCHAR2(20),                     -- push (the terminal calls Hader) / direct (Hader reads it)
        LAST_CONTACT  DATE,
        LAST_UPLOAD   DATE,                             -- last time it sent punches or people
        MODEL         VARCHAR2(100),
        FIRMWARE      VARCHAR2(100),
        USER_COUNT    NUMBER(8),
        FP_COUNT      NUMBER(8),
        FACE_COUNT    NUMBER(8),
        PALM_COUNT    NUMBER(8),
        ATT_COUNT     NUMBER(10),
        PENDING       NUMBER(8),                        -- commands still owed to it
        READ_ONLY     CHAR(1),                          -- Y: Hader may not write to terminals now
        UPDATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_DEVICES_PK PRIMARY KEY (SN)
      )]';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_DEVICE_COMMANDS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_DEVICE_COMMANDS (
        CMD_ID        NUMBER(12)     NOT NULL,          -- Hader's command number
        DEVICE_SN     VARCHAR2(50)   NOT NULL,
        TITLE         VARCHAR2(120),
        STATUS        VARCHAR2(10),                     -- pending, sent, done, failed
        RETURN_CODE   VARCHAR2(20),                     -- the terminal's answer (0 = done)
        CREATED_AT    DATE,
        SENT_AT       DATE,
        RETURNED_AT   DATE,
        CONSTRAINT HADER_DEVICE_COMMANDS_PK PRIMARY KEY (CMD_ID)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_DEVICE_COMMANDS_SN_IX ON HADER_DEVICE_COMMANDS (DEVICE_SN, CREATED_AT)';
  END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE q'[
CREATE OR REPLACE TRIGGER HADER_REQUESTS_BY BEFORE INSERT ON HADER_REQUESTS FOR EACH ROW
BEGIN
  IF SYS_CONTEXT('APEX$SESSION', 'APP_USER') IS NOT NULL THEN
    :NEW.REQUESTED_BY := SUBSTR(SYS_CONTEXT('APEX$SESSION', 'APP_USER'), 1, 100);
  ELSIF :NEW.REQUESTED_BY IS NULL OR SYS_CONTEXT('USERENV', 'SESSION_USER') <> SYS_CONTEXT('USERENV', 'CURRENT_USER') THEN
    :NEW.REQUESTED_BY := SUBSTR(SYS_CONTEXT('USERENV', 'SESSION_USER'), 1, 100);
  END IF;
END;]';
  -- made again over the table as it is now (columns added above): the same text alone would leave it as it was
  EXECUTE IMMEDIATE 'ALTER TRIGGER HADER_REQUESTS_BY COMPILE';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE <> -1031 THEN   -- ORA-01031: this user may not create triggers
    RAISE;
  END IF;
END;
/
COMMENT ON TABLE HADER_PUNCHES IS 'Written by Hader: every punch from the terminals';
COMMENT ON TABLE HADER_ATT_DAILY IS 'Written by Hader: attendance result per employee per day (re-sent when it changes)';
COMMENT ON TABLE HADER_REQUESTS IS 'Written by APEX pages, answered by Hader: sync / recalculation / terminal requests';
COMMENT ON TABLE HADER_DEVICES IS 'Written by Hader: the terminals, their state and counts';
COMMENT ON TABLE HADER_DEVICE_COMMANDS IS 'Written by Hader: commands sent to the terminals in the last days and their answers';
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_views WHERE view_name = 'HADER_V_DEPARTMENTS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE VIEW HADER_V_DEPARTMENTS AS
      SELECT CAST(NULL AS VARCHAR2(50))  AS DEPT_CODE,      -- unique code
             CAST(NULL AS VARCHAR2(120)) AS DEPT_NAME,      -- Arabic name
             CAST(NULL AS VARCHAR2(120)) AS DEPT_NAME_EN    -- English name (optional)
        FROM DUAL WHERE 1 = 0]';
  END IF;

  SELECT COUNT(*) INTO n FROM user_views WHERE view_name = 'HADER_V_EMPLOYEES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE VIEW HADER_V_EMPLOYEES AS
      SELECT CAST(NULL AS VARCHAR2(30))  AS EMP_CODE,       -- number used on the terminals
             CAST(NULL AS VARCHAR2(200)) AS FULL_NAME,      -- Arabic full name
             CAST(NULL AS VARCHAR2(160)) AS NAME_EN,        -- English name (optional)
             CAST(NULL AS VARCHAR2(50))  AS DEPT_CODE,      -- = HADER_V_DEPARTMENTS.DEPT_CODE
             CAST(NULL AS VARCHAR2(120)) AS DEPT_NAME,      -- (optional) used when the department is new
             CAST(NULL AS VARCHAR2(120)) AS POSITION_NAME,  -- job title (optional)
             CAST(NULL AS DATE)          AS HIRE_DATE,      -- (optional)
             CAST(NULL AS VARCHAR2(20))  AS STATUS,         -- A / ACTIVE / 1 = working; anything else = left
             CAST(NULL AS DATE)          AS RESIGN_DATE,    -- (optional)
             CAST(NULL AS VARCHAR2(30))  AS CARD_NO,        -- (optional) badge number
             CAST(NULL AS VARCHAR2(120)) AS EMAIL,          -- (optional) for alerts
             CAST(NULL AS VARCHAR2(50))  AS MOBILE,         -- (optional)
             CAST(NULL AS VARCHAR2(50))  AS AREA_CODE       -- (optional) Hader area = which terminals
        FROM DUAL WHERE 1 = 0]';
  END IF;

  SELECT COUNT(*) INTO n FROM user_views WHERE view_name = 'HADER_V_LEAVES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE VIEW HADER_V_LEAVES AS
      SELECT CAST(NULL AS VARCHAR2(60))  AS LEAVE_ID,       -- unique id in your system
             CAST(NULL AS VARCHAR2(30))  AS EMP_CODE,
             CAST(NULL AS VARCHAR2(10))  AS LEAVE_CODE,     -- e.g. AL, SL
             CAST(NULL AS VARCHAR2(60))  AS LEAVE_NAME,
             CAST(NULL AS DATE)          AS START_TIME,     -- whole days: 00:00 of the first day
             CAST(NULL AS DATE)          AS END_TIME,       -- whole days: 00:00 of the day after the last
             CAST(NULL AS VARCHAR2(20))  AS STATUS          -- APPROVED / PENDING / REJECTED
        FROM DUAL WHERE 1 = 0]';
  END IF;
END;
/
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HDR_EMPLOYEES';
  IF n > 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE OR REPLACE VIEW HADER_V_PEOPLE AS
      SELECT e.EMP_CODE, TO_NCHAR(e.FULL_NAME) AS FULL_NAME, TO_CHAR(e.NAME_EN) AS NAME_EN, e.DEPT_CODE,
             TO_NCHAR(d.NAME) AS DEPT_NAME, TO_CHAR(d.NAME_EN) AS DEPT_NAME_EN, TO_NCHAR(e.POSITION_NAME) AS POSITION_NAME,
             TO_CHAR(e.EMAIL) AS EMAIL, TO_CHAR(e.STATUS) AS STATUS
        FROM HDR_EMPLOYEES e LEFT JOIN HDR_DEPARTMENTS d ON d.DEPT_CODE = e.DEPT_CODE
      UNION ALL
      SELECT TO_CHAR(h.EMP_CODE), TO_NCHAR(h.FULL_NAME), TO_CHAR(h.NAME_EN), TO_CHAR(h.DEPT_CODE),
             TO_NCHAR(NVL(hd.DEPT_NAME, h.DEPT_NAME)), TO_CHAR(hd.DEPT_NAME_EN), TO_NCHAR(h.POSITION_NAME),
             TO_CHAR(h.EMAIL), TO_CHAR(h.STATUS)
        FROM HADER_V_EMPLOYEES h LEFT JOIN HADER_V_DEPARTMENTS hd ON hd.DEPT_CODE = h.DEPT_CODE
       WHERE NOT EXISTS (SELECT 1 FROM HDR_EMPLOYEES x WHERE x.EMP_CODE = TO_CHAR(h.EMP_CODE))]';
  ELSE
    EXECUTE IMMEDIATE q'[
      CREATE OR REPLACE VIEW HADER_V_PEOPLE AS
      SELECT e.EMP_CODE, e.FULL_NAME, e.NAME_EN, e.DEPT_CODE, NVL(d.DEPT_NAME, e.DEPT_NAME) AS DEPT_NAME,
             d.DEPT_NAME_EN, e.POSITION_NAME, e.EMAIL, e.STATUS
        FROM HADER_V_EMPLOYEES e LEFT JOIN HADER_V_DEPARTMENTS d ON d.DEPT_CODE = e.DEPT_CODE]';
  END IF;
END;
/
CREATE OR REPLACE VIEW HADER_V_ATT_REPORT AS
SELECT d.ATT_DATE, d.EMP_CODE, e.FULL_NAME, e.NAME_EN, e.DEPT_CODE,
       e.DEPT_NAME, d.STATUS, d.STATUS_AR, d.STATUS_EN, d.TIMETABLE,
       d.SCHED_IN, d.SCHED_OUT, d.CLOCK_IN, d.CLOCK_OUT, d.REQUIRED_MIN, d.WORKED_MIN, d.LATE_MIN,
       d.EARLY_MIN, d.OT_MIN, d.LEAVE_MIN, d.ABSENT_DAYS, d.ABSENT_MIN, d.LEAVE_CODES, d.HOLIDAY, d.PUNCHES, d.UPDATED_AT,
       -- the status as the program's reports write it: with the holiday's name and the leave codes
       d.STATUS_AR || CASE WHEN d.HOLIDAY IS NOT NULL THEN ' (' || d.HOLIDAY || ')' END
                   || CASE WHEN d.LEAVE_CODES IS NOT NULL THEN ' [' || d.LEAVE_CODES || ']' END AS STATUS_LABEL,
       d.FIRST_PUNCH, d.LAST_PUNCH,
       -- the work days the day counts as and the share attended (a day calculated before 1.6.3: by its status)
       NVL(d.WORKDAY, CASE WHEN d.STATUS IN ('off', 'holiday', 'unscheduled', 'leave') OR d.STATUS IS NULL
                           THEN 0 ELSE 1 END) AS WORKDAY,
       NVL(d.PRESENT, CASE WHEN d.STATUS IN ('present', 'late', 'early', 'late_early', 'incomplete', 'partial_absent')
                           THEN 1 ELSE 0 END) AS PRESENT,
       NVL(d.MISSED_IN, 0) + NVL(d.MISSED_OUT, CASE WHEN d.MISSED_IN IS NULL AND d.STATUS = 'incomplete' THEN 1 ELSE 0 END)
         AS MISSED_PUNCHES,
       NVL(d.MISSED_IN, 0) AS MISSED_IN, NVL(d.MISSED_OUT, 0) AS MISSED_OUT,
       -- the missing punches as the program writes them (a split day can miss two)
       REPLACE(REPLACE(REPLACE(d.MISSED_LIST, 'missed_in', UNISTR('\0628\062F\0648\0646 \062F\062E\0648\0644')),
               'missed_out', UNISTR('\0628\062F\0648\0646 \062E\0631\0648\062C')), ',', UNISTR('\060C ')) AS MISSED_TEXT,
       -- 0/1 flags, so APEX pages never have to list statuses (sum them for counts and rates)
       CASE WHEN d.STATUS IN ('off', 'holiday', 'unscheduled') THEN 0 ELSE 1 END AS IS_EXPECTED,
       CASE WHEN d.STATUS IN ('present', 'late', 'early', 'late_early', 'incomplete', 'partial_absent')
            THEN 1 ELSE 0 END AS IS_PRESENT,
       CASE WHEN d.LATE_MIN > 0 THEN 1 ELSE 0 END AS IS_LATE,
       CASE WHEN d.EARLY_MIN > 0 THEN 1 ELSE 0 END AS IS_EARLY,
       CASE WHEN d.OT_MIN > 0 THEN 1 ELSE 0 END AS IS_OT,
       CASE WHEN d.STATUS = 'absent' THEN 1 ELSE 0 END AS IS_ABSENT,
       CASE WHEN d.STATUS = 'partial_absent' THEN 1 ELSE 0 END AS IS_PARTIAL,
       CASE WHEN d.STATUS = 'leave' THEN 1 ELSE 0 END AS IS_LEAVE,
       CASE WHEN d.STATUS = 'holiday' THEN 1 ELSE 0 END AS IS_HOLIDAY,
       CASE WHEN d.STATUS = 'off' THEN 1 ELSE 0 END AS IS_OFF
  FROM HADER_ATT_DAILY d
  LEFT JOIN HADER_V_PEOPLE e ON e.EMP_CODE = d.EMP_CODE;
CREATE OR REPLACE VIEW HADER_V_MONTH_SUMMARY AS
SELECT TRUNC(ATT_DATE, 'MM') AS MONTH_START, TO_CHAR(ATT_DATE, 'YYYY-MM') AS MONTH, EMP_CODE,
       MAX(FULL_NAME) AS FULL_NAME, MAX(NAME_EN) AS NAME_EN, MAX(DEPT_CODE) AS DEPT_CODE, MAX(DEPT_NAME) AS DEPT_NAME,
       SUM(WORKDAY) AS WORK_DAYS, SUM(PRESENT) AS PRESENT_DAYS, SUM(ABSENT_DAYS) AS ABSENT_DAYS,
       SUM(IS_ABSENT) AS ABSENT_WHOLE_DAYS, SUM(IS_PARTIAL) AS PARTIAL_ABSENT_DAYS, SUM(ABSENT_MIN) AS ABSENT_MIN,
       SUM(IS_LEAVE) AS LEAVE_DAYS, SUM(IS_LATE) AS LATE_TIMES, SUM(LATE_MIN) AS LATE_MIN,
       SUM(IS_EARLY) AS EARLY_TIMES, SUM(EARLY_MIN) AS EARLY_MIN,
       SUM(OT_MIN) AS OT_MIN, SUM(LEAVE_MIN) AS LEAVE_MIN, SUM(WORKED_MIN) AS WORKED_MIN, SUM(REQUIRED_MIN) AS REQUIRED_MIN,
       SUM(MISSED_PUNCHES) AS MISSED_PUNCHES, SUM(IS_HOLIDAY) AS HOLIDAYS, SUM(IS_OFF) AS OFF_DAYS,
       MAX(UPDATED_AT) AS UPDATED_AT
  FROM HADER_V_ATT_REPORT
 GROUP BY TRUNC(ATT_DATE, 'MM'), TO_CHAR(ATT_DATE, 'YYYY-MM'), EMP_CODE;

-- ---------------------------------------------------------------- hdr_schema.sql
DECLARE
  n NUMBER;
  PROCEDURE ddl (p_name IN VARCHAR2, p_sql IN VARCHAR2) IS
    n NUMBER;
  BEGIN
    SELECT COUNT(*) INTO n FROM user_objects WHERE object_name = p_name;
    IF n = 0 THEN
      EXECUTE IMMEDIATE p_sql;
    END IF;
  END;
  PROCEDURE col (p_table IN VARCHAR2, p_col IN VARCHAR2, p_def IN VARCHAR2) IS
    n NUMBER;
  BEGIN
    SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = p_table AND column_name = p_col;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table || ' ADD (' || p_col || ' ' || p_def || ')';
    END IF;
  END;
BEGIN
  ddl('HDR_SEQ', 'CREATE SEQUENCE HDR_SEQ CACHE 100');

  -- ---------------------------------------------------------------- settings
  ddl('HDR_SETTINGS', q'[
    CREATE TABLE HDR_SETTINGS (
      SKEY   VARCHAR2(60) NOT NULL,
      SVALUE VARCHAR2(4000),
      CONSTRAINT HDR_SETTINGS_PK PRIMARY KEY (SKEY))]');

  -- the English of APEX app 141's own words (2.3.6): its pages, items and buttons are written in Arabic and their
  -- English is a translation of them (HDR_UI.publish_english); filled by hdr_i18n.sql from apex/i18n/ar_en.json
  ddl('HDR_I18N', q'[
    CREATE TABLE HDR_I18N (
      AR NVARCHAR2(1000) NOT NULL,
      EN VARCHAR2(2000)  NOT NULL,
      CONSTRAINT HDR_I18N_PK PRIMARY KEY (AR))]');

