  ddl('HDR_OVERTIME_ST_IX', 'CREATE INDEX HDR_OVERTIME_ST_IX ON HDR_OVERTIME (STATUS, CREATED_AT)');

  -- dated versions (HDR_POLICY): an edit of a timetable, of a shift (its cycle and days) or of the attendance
  -- rules never changes the days before it. Each row is the whole version in force from EFFECTIVE_FROM, rebuilt
  -- from the edits whenever one is added (the program's attendance_policy, hader/policy_history.py):
  --   VER_KIND baseline  what applied before the first edit, from the beginning of time (0001-01-01)
  --            edit      CHANGED: the columns (rules: the keys) this edit set itself
  --            return    the day after a period's last day: what that period set comes back (CLOSES: its edit)
  -- Without a row the timetable / shift / rule itself (HDR_TIMETABLES, HDR_SHIFTS, HDR_SETTINGS) applies.
  ddl('HDR_TIMETABLE_VERSIONS', q'[
    CREATE TABLE HDR_TIMETABLE_VERSIONS (
      VER_ID         NUMBER         NOT NULL,
      TT_ID          NUMBER         NOT NULL,
      EFFECTIVE_FROM DATE           NOT NULL,
      VER_KIND       VARCHAR2(10)   DEFAULT 'edit' NOT NULL,
      CLOSES         NUMBER,
      CHANGED        VARCHAR2(1000),
      ALIAS          NVARCHAR2(60),
      KIND           VARCHAR2(10),
      CHECK_IN       VARCHAR2(5),
      CHECK_OUT      VARCHAR2(5),
      IN_AHEAD       NUMBER(5),
      IN_ABOVE       NUMBER(5),
      OUT_AHEAD      NUMBER(5),
      OUT_ABOVE      NUMBER(5),
      LATE_GRACE     NUMBER(5),
      EARLY_GRACE    NUMBER(5),
      MUST_IN        CHAR(1),
      MUST_OUT       CHAR(1),
      BREAK_START    VARCHAR2(5),
      BREAK_END      VARCHAR2(5),
      WORK_MINUTES   NUMBER(5),
      WORKDAY        NUMBER(4,2),
      COLOR          VARCHAR2(10),
      REASON         NVARCHAR2(300),
      ACTOR          VARCHAR2(255),
      CREATED_AT     DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_TIMETABLE_VERSIONS_PK PRIMARY KEY (VER_ID))]');
  ddl('HDR_TIMETABLE_VERSIONS_IX', 'CREATE INDEX HDR_TIMETABLE_VERSIONS_IX ON HDR_TIMETABLE_VERSIONS (TT_ID, EFFECTIVE_FROM)');

  ddl('HDR_SHIFT_VERSIONS', q'[
    CREATE TABLE HDR_SHIFT_VERSIONS (
      VER_ID         NUMBER         NOT NULL,
      SHIFT_ID       NUMBER         NOT NULL,
      EFFECTIVE_FROM DATE           NOT NULL,
      VER_KIND       VARCHAR2(10)   DEFAULT 'edit' NOT NULL,
      CLOSES         NUMBER,
      CHANGED        VARCHAR2(1000),                       -- CYCLE_UNIT, CYCLE, DAYS
      CYCLE_UNIT     VARCHAR2(5),
      CYCLE          NUMBER(3),
      REASON         NVARCHAR2(300),
      ACTOR          VARCHAR2(255),
      CREATED_AT     DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_SHIFT_VERSIONS_PK PRIMARY KEY (VER_ID))]');
  ddl('HDR_SHIFT_VERSIONS_IX', 'CREATE INDEX HDR_SHIFT_VERSIONS_IX ON HDR_SHIFT_VERSIONS (SHIFT_ID, EFFECTIVE_FROM)');
  -- the days of a shift's version, as HDR_SHIFT_DAYS holds them for the shift itself
  ddl('HDR_SHIFT_VERSION_DAYS', q'[
    CREATE TABLE HDR_SHIFT_VERSION_DAYS (
      VER_ID    NUMBER    NOT NULL,
      DAY_INDEX NUMBER(4) NOT NULL,
      TT_ID     NUMBER    NOT NULL,
      CONSTRAINT HDR_SHIFT_VERSION_DAYS_PK PRIMARY KEY (VER_ID, DAY_INDEX, TT_ID))]');
  ddl('HDR_SHIFT_VERSION_DAYS_TT_IX', 'CREATE INDEX HDR_SHIFT_VERSION_DAYS_TT_IX ON HDR_SHIFT_VERSION_DAYS (TT_ID)');

  ddl('HDR_RULE_VERSIONS', q'[
    CREATE TABLE HDR_RULE_VERSIONS (
      VER_ID         NUMBER         NOT NULL,
      EFFECTIVE_FROM DATE           NOT NULL,
      VER_KIND       VARCHAR2(10)   DEFAULT 'edit' NOT NULL,
      CLOSES         NUMBER,
      CHANGED        VARCHAR2(1000),                       -- the att.* keys
      REASON         NVARCHAR2(300),
      ACTOR          VARCHAR2(255),
      CREATED_AT     DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_RULE_VERSIONS_PK PRIMARY KEY (VER_ID))]');
  -- the rules of a version, as HDR_SETTINGS holds them (att.* keys and values)
  ddl('HDR_RULE_VERSION_VALUES', q'[
    CREATE TABLE HDR_RULE_VERSION_VALUES (
      VER_ID NUMBER         NOT NULL,
      SKEY   VARCHAR2(60)   NOT NULL,
      SVALUE VARCHAR2(4000),
      CONSTRAINT HDR_RULE_VERSION_VALUES_PK PRIMARY KEY (VER_ID, SKEY))]');

  -- the accounts of the Hader program as APEX app 141 knows them (an APEX user is the account of the same name):
  -- the permissions of its role (PERMISSIONS: attendance.approve, attendance.approve_all - the general manager -,
  -- system.admin ...), the employee it is (EMP_CODE: their own requests are never theirs to decide). SOURCE HADER:
  -- kept by the Hader server; APEX: added in the app. With no account at all, every APEX user decides as before.
  ddl('HDR_USERS', q'[
    CREATE TABLE HDR_USERS (
      USERNAME    VARCHAR2(255)  NOT NULL,
      FULL_NAME   NVARCHAR2(100),
      EMP_CODE    VARCHAR2(30),
      PERMISSIONS VARCHAR2(1000),
      ACTIVE      CHAR(1)        DEFAULT 'Y' NOT NULL,
      SOURCE      VARCHAR2(10)   DEFAULT 'APEX' NOT NULL,
      UPDATED_AT  DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_USERS_PK PRIMARY KEY (USERNAME))]');

  -- who decides a department's requests (leave, manual punches, overtime) and those of the departments under it:
  -- its head, and deputies standing in for the head, each for a period (both days counted) or always (no dates).
  -- The program's department_approver (hader/approvals.py); deciding still needs attendance.approve.
  ddl('HDR_APPROVERS', q'[
    CREATE TABLE HDR_APPROVERS (
      APPROVER_ID NUMBER        NOT NULL,
      DEPT_CODE   VARCHAR2(50)  NOT NULL,
      USERNAME    VARCHAR2(255) NOT NULL,
      KIND        VARCHAR2(10)  DEFAULT 'head' NOT NULL,     -- head / deputy
      START_DATE  DATE,
      END_DATE    DATE,
      CONSTRAINT HDR_APPROVERS_PK PRIMARY KEY (APPROVER_ID))]');
  ddl('HDR_APPROVERS_DEPT_IX', 'CREATE INDEX HDR_APPROVERS_DEPT_IX ON HDR_APPROVERS (DEPT_CODE)');
  ddl('HDR_APPROVERS_USER_IX', 'CREATE INDEX HDR_APPROVERS_USER_IX ON HDR_APPROVERS (USERNAME)');

  -- the bell of APEX app 141: the program's alerts (hader/alerts.py), each event told once (HDR_ALERTS)
  ddl('HDR_NOTIFICATIONS', q'[
    CREATE TABLE HDR_NOTIFICATIONS (
      NOTE_ID    NUMBER         NOT NULL,
      AKEY       VARCHAR2(160)  NOT NULL,                  -- the event, as the program's alert log keys it
      KIND       VARCHAR2(20)   NOT NULL,                  -- late / absent / missing_out / device_offline / ...
      LVL        VARCHAR2(10)   DEFAULT 'info' NOT NULL,   -- good / info / warn / bad
      TITLE      NVARCHAR2(200),
      BODY       NVARCHAR2(1000),
      PAGE_ID    NUMBER(6),                                -- the page of APEX app 141 it opens
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_NOTIFICATIONS_PK PRIMARY KEY (NOTE_ID),
      CONSTRAINT HDR_NOTIFICATIONS_UK UNIQUE (AKEY))]');
  ddl('HDR_NOTIFICATIONS_AT_IX', 'CREATE INDEX HDR_NOTIFICATIONS_AT_IX ON HDR_NOTIFICATIONS (CREATED_AT)');
  -- who has read which (an APEX user)
  ddl('HDR_NOTIFICATION_READS', q'[
    CREATE TABLE HDR_NOTIFICATION_READS (
      NOTE_ID  NUMBER         NOT NULL,
      USERNAME VARCHAR2(255)  NOT NULL,
      READ_AT  DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_NOTIFICATION_READS_PK PRIMARY KEY (NOTE_ID, USERNAME))]');

  -- the Hader assistant in APEX app 141: a question, or a decision on a proposal, waits here; the Hader server, connected
  -- to this schema, takes it within seconds and writes the answer as it grows (hader/ai/apex.py, HDR_UI.ai_*)
  ddl('HDR_AI_CHAT', q'[
    CREATE TABLE HDR_AI_CHAT (
      REQ_ID     NUMBER         NOT NULL,
      KIND       VARCHAR2(10)   DEFAULT 'ASK' NOT NULL,   -- ASK / RUN / DECLINE (a proposal) / DROP (a conversation)
      APEX_USER  VARCHAR2(255)  NOT NULL,
      CONV_ID    NUMBER,                                   -- the conversation, as the Hader server numbers it
      REF_ID     NUMBER,                                   -- RUN / DECLINE: the question whose answer proposed it
      ACTION_ID  NUMBER,                                   -- RUN / DECLINE: the proposal
      QUESTION   CLOB,
      STATUS     VARCHAR2(10)   DEFAULT 'NEW' NOT NULL,   -- NEW / RUNNING / STOP (asked to stop) / DONE / FAILED
      REPLY      CLOB,                                     -- the answer for the page: JSON in plain ASCII
      ASKED_AT   DATE           DEFAULT SYSDATE NOT NULL,
      UPDATED_AT DATE,
      CONSTRAINT HDR_AI_CHAT_PK PRIMARY KEY (REQ_ID))]');
  ddl('HDR_AI_CHAT_ST_IX', 'CREATE INDEX HDR_AI_CHAT_ST_IX ON HDR_AI_CHAT (STATUS)');
  ddl('HDR_AI_CHAT_U_IX', 'CREATE INDEX HDR_AI_CHAT_U_IX ON HDR_AI_CHAT (APEX_USER, CONV_ID)');
  -- a file the assistant made for an APEX user (an Excel sheet, a ZIP of pictures): copied here by the Hader server
  -- with the answer, so the page downloads it (HDR_UI.ai_file); it goes with its conversation
  ddl('HDR_AI_FILES', q'[
    CREATE TABLE HDR_AI_FILES (
      FILE_ID    NUMBER         NOT NULL,                  -- the file's number in the Hader server
      APEX_USER  VARCHAR2(255)  NOT NULL,
      CONV_ID    NUMBER,
      NAME       VARCHAR2(200)  NOT NULL,
      MIME       VARCHAR2(100)  NOT NULL,
      CONTENT    BLOB,
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_AI_FILES_PK PRIMARY KEY (FILE_ID))]');
  ddl('HDR_AI_FILES_U_IX', 'CREATE INDEX HDR_AI_FILES_U_IX ON HDR_AI_FILES (APEX_USER, CONV_ID)');
  -- a file an APEX user attaches to a question (a picture, a PDF, a sheet, a ZIP of pictures): kept here until the
  -- Hader server reads it with the question (HDR_UI.ai_upload, ai_ask); it goes with its conversation
  ddl('HDR_AI_UPLOADS', q'[
    CREATE TABLE HDR_AI_UPLOADS (
      UP_ID      NUMBER         NOT NULL,
      APEX_USER  VARCHAR2(255)  NOT NULL,
      REQ_ID     NUMBER,                                   -- the question it was sent with (none yet: still to send)
      NAME       VARCHAR2(200)  NOT NULL,
      MIME       VARCHAR2(100)  NOT NULL,
      BYTES      NUMBER         NOT NULL,
      CONTENT    BLOB,
      DONE       VARCHAR2(1)    DEFAULT 'N' NOT NULL,     -- Y: every part has come (only then is it sent)
      FILE_ID    NUMBER,                                   -- its number in the Hader server, once read there
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_AI_UPLOADS_PK PRIMARY KEY (UP_ID))]');
  ddl('HDR_AI_UPLOADS_U_IX', 'CREATE INDEX HDR_AI_UPLOADS_U_IX ON HDR_AI_UPLOADS (APEX_USER, REQ_ID)');
  ddl('HDR_AI_UPLOADS_R_IX', 'CREATE INDEX HDR_AI_UPLOADS_R_IX ON HDR_AI_UPLOADS (REQ_ID)');

  -- work the background job picks up: EMP (employee or areas changed -> terminals), DEV (a terminal's
  -- area changed -> its people), ALL (rules / timetables / holidays changed -> recalculate from a date)
  ddl('HDR_PENDING', q'[
    CREATE TABLE HDR_PENDING (
      KIND      VARCHAR2(10)   NOT NULL,
      KEY_VAL   VARCHAR2(60)   NOT NULL,
      ADDED     VARCHAR2(4000),
      REMOVED   VARCHAR2(4000),
      DELETED   CHAR(1)        DEFAULT 'N' NOT NULL,
      FROM_DATE DATE,
      MARKED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_PENDING_PK PRIMARY KEY (KIND, KEY_VAL))]');

  -- the interface tables shared with the Hader link (created by hader_interface.sql) get what native mode needs
  col('HDR_EMPLOYEES', 'ATT_SOURCE', 'VARCHAR2(10)');
  col('HDR_EMPLOYEES', 'GENDER', 'VARCHAR2(1)');          -- M / F (the leave types' rules)
  col('HDR_LEAVES', 'RELATION', 'VARCHAR2(10)');          -- the relative a bereavement leave is for (HDR_RELATIONS)
  -- the leave balance movements this edition makes (hader/leave_moves.py): a month's lateness taken from a leave
  ddl('HDR_LEAVE_MOVES', q'[
    CREATE TABLE HDR_LEAVE_MOVES (
      MOVE_ID    NUMBER         NOT NULL,
      EMP_CODE   VARCHAR2(30)   NOT NULL,
      MONTH      VARCHAR2(7)    NOT NULL,
      SOURCE     VARCHAR2(10)   DEFAULT 'late' NOT NULL,
      KIND       VARCHAR2(1)    DEFAULT 'D' NOT NULL,
      LEAVE_CODE VARCHAR2(10),
      TITLE      NVARCHAR2(250),
      MINUTES    NUMBER(7)      DEFAULT 0 NOT NULL,
      DAYS       NUMBER(5)      DEFAULT 0 NOT NULL,
      HOURS      NUMBER(3)      DEFAULT 0 NOT NULL,
      MINS       NUMBER(3)      DEFAULT 0 NOT NULL,
      STATUS     VARCHAR2(10)   DEFAULT 'pending' NOT NULL,
      ERROR      VARCHAR2(250),
      POSTED_AT  DATE,
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_LEAVE_MOVES_PK PRIMARY KEY (MOVE_ID))]');
  -- one employee's month once (the program writes what it posts here too: hader/leave_moves.py)
  ddl('HDR_LEAVE_MOVES_UK', 'CREATE UNIQUE INDEX HDR_LEAVE_MOVES_UK ON HDR_LEAVE_MOVES (MONTH, EMP_CODE, SOURCE)');
  -- the relatives of a bereavement leave and its days for each (the HR system's, hr.table_relations)
  ddl('HDR_RELATIONS', q'[
    CREATE TABLE HDR_RELATIONS (
      REL_CODE VARCHAR2(10)    NOT NULL,
      NAME     NVARCHAR2(250)  NOT NULL,
      DAYS     NUMBER(5,1),
      CONSTRAINT HDR_RELATIONS_PK PRIMARY KEY (REL_CODE))]');
  -- the HR system's limits of an attendance type on its shift (hr.col_*): a month's times and minutes late,
  -- the overtime hours of a month and of a week
  col('HDR_SHIFTS', 'LIM_LATE_TIMES', 'NUMBER(5)');
  col('HDR_SHIFTS', 'LIM_LATE_MIN', 'NUMBER(7)');
  col('HDR_SHIFTS', 'LIM_OT_MONTH', 'NUMBER(7,2)');
  col('HDR_SHIFTS', 'LIM_OT_WEEK', 'NUMBER(7,2)');     -- the HR system's attendance source (hr.source_column)
  col('HADER_PUNCHES', 'WORK_CODE', 'VARCHAR2(20)');
  col('HADER_PUNCHES', 'VERIFY_CODE', 'NUMBER(3)');      -- the terminal's own verify number (for the HR punches table)
  col('HADER_PUNCHES', 'TEMPERATURE', 'NUMBER(4,1)');   -- the body temperature a thermal terminal took
  col('HADER_PUNCHES', 'UPLOADED_AT', 'DATE');         -- reached the server, on the terminal's clock (2.3.7)
  col('HADER_PUNCHES', 'ORIG_TIME', 'DATE');           -- its time before a clock fix (2.3.8)
  col('HADER_PUNCHES', 'FIXED_AT', 'DATE');
  -- a terminal that called in and waits for an administrator to approve it (adms.auto_add = N)
  col('HDR_DEVICES', 'PENDING', q'[CHAR(1) DEFAULT 'N' NOT NULL]');
  -- push 3.x firmware keeps a mark for its biometric table (BIODATAStamp); some firmware refuses table queries
  -- (-1004): it is then asked by clearing its marks, so it sends everything by itself (hader/adms/sync.py)
  col('HDR_DEVICES', 'BIO_STAMP', 'VARCHAR2(30)');
  col('HDR_DEVICES', 'NO_QUERY', q'[CHAR(1) DEFAULT 'N' NOT NULL]');
  -- the terminal's day it was last asked for the people it holds (once a day, hader/adms/sync.py users_daily)
  col('HDR_DEVICES', 'USERS_DAY', 'VARCHAR2(10)');
  -- 2.3.6: pointed to a server by an administrator: its first call until then is taken from where it comes, and binds it
  col('HDR_DEVICES', 'REBIND_UNTIL', 'DATE');
  -- 2.3.6: an accepted terminal that called from an address it is not bound to: shown for the administrator to accept
  col('HDR_DEVICES', 'MOVED_IP', 'VARCHAR2(45)');
  col('HDR_DEVICES', 'MOVED_AT', 'DATE');
  col('HADER_ATT_DAILY', 'ABSENT_MIN', 'NUMBER(6)');
  -- when a request was decided, and the approver's reason told to the employee (the program's decided_at and
  -- decision_note)
  col('HDR_LEAVES', 'DECIDED_AT', 'DATE');
  col('HDR_LEAVES', 'DECISION_NOTE', 'NVARCHAR2(250)');
  col('HDR_MANUAL_PUNCHES', 'DECIDED_AT', 'DATE');
  col('HDR_MANUAL_PUNCHES', 'DECISION_NOTE', 'NVARCHAR2(250)');
  col('HDR_OVERTIME', 'DECIDED_AT', 'DATE');
  col('HDR_OVERTIME', 'DECISION_NOTE', 'NVARCHAR2(250)');
  -- the employee an alert is about: the bell shows it to those who decide that employee's requests
  col('HDR_NOTIFICATIONS', 'EMP_CODE', 'VARCHAR2(30)');
  -- an account's role in the Hader program and whether it holds every permission there (the users page shows them)
  col('HDR_USERS', 'ROLE_NAME', 'NVARCHAR2(100)');
  col('HDR_USERS', 'IS_SUPER', q'[CHAR(1) DEFAULT 'N' NOT NULL]');
  ddl('HADER_PUNCHES_TIME_IX', 'CREATE INDEX HADER_PUNCHES_TIME_IX ON HADER_PUNCHES (PUNCH_TIME)');
  -- the punches taken lately (by when they were written): the HR punches table looks at the last minutes again,
  -- the Hader server's copy reads them in that order
  ddl('HADER_PUNCHES_CREATED_IX', 'CREATE INDEX HADER_PUNCHES_CREATED_IX ON HADER_PUNCHES (CREATED_AT, PUNCH_ID)');

  -- the same punch twice (same person, time and terminal), found in HADER_PUNCHES when Hader took over a
  -- schema the Hader program had written to: kept here, never lost (HDR_JOBS.activate moves them)
  ddl('HDR_PUNCHES_DUPLICATES', q'[
    CREATE TABLE HDR_PUNCHES_DUPLICATES (
      PUNCH_ID    NUMBER(12)     NOT NULL,
      EMP_CODE    VARCHAR2(30),
      PUNCH_TIME  DATE,
      PUNCH_STATE NUMBER(3),
      STATE_NAME  VARCHAR2(30),
      VERIFY_TYPE VARCHAR2(30),
      DEVICE_SN   VARCHAR2(50),
      DEVICE_NAME VARCHAR2(100),
      SOURCE      VARCHAR2(10),
      CREATED_AT  DATE,
      MOVED_AT    DATE DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_PUNCHES_DUPLICATES_PK PRIMARY KEY (PUNCH_ID))]');
  -- a punch is stored once: the index is made here when HADER_PUNCHES has no such pair, else by HDR_JOBS.activate
  SELECT COUNT(*) INTO n FROM user_objects WHERE object_name = 'HADER_PUNCHES_UK';
  IF n = 0 THEN
    SELECT COUNT(*) INTO n FROM (SELECT 1 FROM HADER_PUNCHES GROUP BY EMP_CODE, PUNCH_TIME, DEVICE_SN HAVING COUNT(*) > 1)
     WHERE ROWNUM = 1;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX HADER_PUNCHES_UK ON HADER_PUNCHES (EMP_CODE, PUNCH_TIME, DEVICE_SN)';
    END IF;
  END IF;

  -- punches the HR system's own punches table (hr_table.*) has not taken yet: waiting for their number to be in
  -- the HR employees table, or refused by the table (its trigger, a column too small) and tried again
  ddl('HDR_HR_HOLD', q'[
    CREATE TABLE HDR_HR_HOLD (
      PUNCH_ID NUMBER(12)     NOT NULL,
      KIND     VARCHAR2(10)   NOT NULL,          -- waiting / refused / clock (a clock gone back to midnight)
      REASON   VARCHAR2(400),
      HELD_AT  DATE DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_HR_HOLD_PK PRIMARY KEY (PUNCH_ID))]');
END;
/
DECLARE
  n NUMBER;
  l_punches NUMBER;
  l_ours NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM HDR_SETTINGS WHERE SKEY = 'native.active';
  IF n = 0 THEN
    SELECT COUNT(*) INTO l_punches FROM HADER_PUNCHES WHERE ROWNUM = 1;
    SELECT COUNT(*) INTO l_ours FROM (SELECT 1 FROM HDR_DEVICES UNION ALL SELECT 1 FROM HDR_EMPLOYEES
                                       UNION ALL SELECT 1 FROM HDR_TRAFFIC) WHERE ROWNUM = 1;
    INSERT INTO HDR_SETTINGS (SKEY, SVALUE)
    VALUES ('native.active', CASE WHEN l_punches > 0 AND l_ours = 0 THEN 'N' ELSE 'Y' END);
    COMMIT;
  END IF;
END;
/
DECLARE
  n     NUMBER;
  l_top NUMBER := 0;
BEGIN
  SELECT COUNT(*) INTO n FROM user_sequences WHERE sequence_name = 'HDR_LOG_SEQ';
  IF n = 0 THEN
    FOR t IN (SELECT 'HDR_TRAFFIC' tab FROM DUAL UNION ALL SELECT 'HDR_ERRLOG' FROM DUAL
              UNION ALL SELECT 'HDR_REJECTS' FROM DUAL UNION ALL SELECT 'HDR_OPLOG' FROM DUAL) LOOP
      EXECUTE IMMEDIATE 'SELECT GREATEST(:1, NVL(MAX(LOG_ID), 0)) FROM ' || t.tab INTO l_top USING l_top;
    END LOOP;
    SELECT GREATEST(l_top, NVL(MAX(LAST_NUMBER), 0)) INTO l_top FROM user_sequences WHERE sequence_name = 'HDR_SEQ';
    -- room for what the code still running during the upgrade logs with HDR_SEQ meanwhile
    EXECUTE IMMEDIATE 'CREATE SEQUENCE HDR_LOG_SEQ START WITH ' || TO_CHAR(l_top + 10000) || ' CACHE 100';
  END IF;
END;
/
CREATE OR REPLACE VIEW HDR_V_RETURN_PUNCHES AS
SELECT r.RETURN_ID, r.SN, r.RETURNED_AT, r.LAST_SEEN, p.PUNCH_ID, p.EMP_CODE, p.PUNCH_TIME, p.UPLOADED_AT
  FROM HDR_RETURNS r
  JOIN HADER_PUNCHES p
    ON p.DEVICE_SN = r.SN
   AND NVL(p.SOURCE, 'device') IN ('device', 'tcp')
   AND p.ORIG_TIME IS NULL
   AND p.UPLOADED_AT BETWEEN r.RETURNED_AT - 1 / 1440 AND r.RETURNED_AT + 1 / 24
   AND p.PUNCH_TIME >= TRUNC(r.RETURNED_AT)
   AND p.PUNCH_TIME < r.RETURNED_AT - 15 / 1440
   AND p.PUNCH_TIME < TRUNC(r.RETURNED_AT) + (r.RETURNED_AT - r.LAST_SEEN)
 WHERE r.STATUS = 'open';
CREATE OR REPLACE VIEW HDR_V_SETTINGS AS
SELECT SKEY, SVALUE FROM HDR_SETTINGS
 WHERE SKEY <> 'adms.gate_key' AND NOT REGEXP_LIKE(LOWER(SKEY), '(key|secret|password|passwd|token)$');
CREATE OR REPLACE VIEW HDR_V_POLICY_VERSIONS AS
SELECT 'timetable' AS SCOPE, v.TT_ID AS TARGET_ID, t.ALIAS AS TARGET_NAME, v.VER_ID, v.VER_KIND,
       v.EFFECTIVE_FROM AS DATE_FROM,
       (SELECT MIN(x.EFFECTIVE_FROM) FROM HDR_TIMETABLE_VERSIONS x
         WHERE x.TT_ID = v.TT_ID AND x.EFFECTIVE_FROM > v.EFFECTIVE_FROM) - 1 AS DATE_TO,
       CASE WHEN EXISTS (
         SELECT 1 FROM HDR_TIMETABLE_VERSIONS x LEFT JOIN HDR_TIMETABLE_VERSIONS xc ON xc.VER_ID = x.CLOSES
          WHERE x.TT_ID = v.TT_ID AND x.EFFECTIVE_FROM = v.EFFECTIVE_FROM AND x.VER_ID <> v.VER_ID
            AND ((x.VER_KIND <> 'return' AND (v.VER_KIND = 'return' OR x.VER_ID > v.VER_ID))
                 OR (x.VER_KIND = 'return' AND v.VER_KIND = 'return'
                     AND (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') < NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                          OR (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') = NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                              AND (x.CLOSES < v.CLOSES OR (x.CLOSES = v.CLOSES AND x.VER_ID > v.VER_ID)))))))
       THEN 'N' ELSE 'Y' END AS APPLIED,
       v.CLOSES, v.CHANGED, v.REASON, v.ACTOR, v.CREATED_AT
  FROM HDR_TIMETABLE_VERSIONS v
  LEFT JOIN HDR_TIMETABLE_VERSIONS vc ON vc.VER_ID = v.CLOSES
  LEFT JOIN HDR_TIMETABLES t ON t.TT_ID = v.TT_ID
UNION ALL
SELECT 'shift', v.SHIFT_ID, s.ALIAS, v.VER_ID, v.VER_KIND, v.EFFECTIVE_FROM,
       (SELECT MIN(x.EFFECTIVE_FROM) FROM HDR_SHIFT_VERSIONS x
         WHERE x.SHIFT_ID = v.SHIFT_ID AND x.EFFECTIVE_FROM > v.EFFECTIVE_FROM) - 1,
       CASE WHEN EXISTS (
         SELECT 1 FROM HDR_SHIFT_VERSIONS x LEFT JOIN HDR_SHIFT_VERSIONS xc ON xc.VER_ID = x.CLOSES
          WHERE x.SHIFT_ID = v.SHIFT_ID AND x.EFFECTIVE_FROM = v.EFFECTIVE_FROM AND x.VER_ID <> v.VER_ID
            AND ((x.VER_KIND <> 'return' AND (v.VER_KIND = 'return' OR x.VER_ID > v.VER_ID))
                 OR (x.VER_KIND = 'return' AND v.VER_KIND = 'return'
                     AND (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') < NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                          OR (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') = NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                              AND (x.CLOSES < v.CLOSES OR (x.CLOSES = v.CLOSES AND x.VER_ID > v.VER_ID)))))))
       THEN 'N' ELSE 'Y' END,
       v.CLOSES, v.CHANGED, v.REASON, v.ACTOR, v.CREATED_AT
  FROM HDR_SHIFT_VERSIONS v
  LEFT JOIN HDR_SHIFT_VERSIONS vc ON vc.VER_ID = v.CLOSES
  LEFT JOIN HDR_SHIFTS s ON s.SHIFT_ID = v.SHIFT_ID
UNION ALL
SELECT 'rules', 0, CAST(NULL AS NVARCHAR2(60)), v.VER_ID, v.VER_KIND, v.EFFECTIVE_FROM,
       (SELECT MIN(x.EFFECTIVE_FROM) FROM HDR_RULE_VERSIONS x WHERE x.EFFECTIVE_FROM > v.EFFECTIVE_FROM) - 1,
       CASE WHEN EXISTS (
         SELECT 1 FROM HDR_RULE_VERSIONS x LEFT JOIN HDR_RULE_VERSIONS xc ON xc.VER_ID = x.CLOSES
          WHERE x.EFFECTIVE_FROM = v.EFFECTIVE_FROM AND x.VER_ID <> v.VER_ID
            AND ((x.VER_KIND <> 'return' AND (v.VER_KIND = 'return' OR x.VER_ID > v.VER_ID))
                 OR (x.VER_KIND = 'return' AND v.VER_KIND = 'return'
                     AND (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') < NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                          OR (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') = NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                              AND (x.CLOSES < v.CLOSES OR (x.CLOSES = v.CLOSES AND x.VER_ID > v.VER_ID)))))))
       THEN 'N' ELSE 'Y' END,
       v.CLOSES, v.CHANGED, v.REASON, v.ACTOR, v.CREATED_AT
  FROM HDR_RULE_VERSIONS v
  LEFT JOIN HDR_RULE_VERSIONS vc ON vc.VER_ID = v.CLOSES;
CREATE OR REPLACE TRIGGER HDR_LEAVE_MOVES_BI BEFORE INSERT ON HDR_LEAVE_MOVES FOR EACH ROW
BEGIN
  IF :NEW.MOVE_ID IS NULL THEN :NEW.MOVE_ID := HDR_SEQ.NEXTVAL; END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_AREAS_BI BEFORE INSERT ON HDR_AREAS FOR EACH ROW
BEGIN
  IF :NEW.AREA_ID IS NULL THEN :NEW.AREA_ID := HDR_SEQ.NEXTVAL; END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_EMPLOYEES_BI BEFORE INSERT OR UPDATE ON HDR_EMPLOYEES FOR EACH ROW
BEGIN
  IF INSERTING AND :NEW.EMP_ID IS NULL THEN :NEW.EMP_ID := HDR_SEQ.NEXTVAL; END IF;
  IF (INSERTING OR :NEW.EMP_CODE <> :OLD.EMP_CODE)
     AND NOT NVL(REGEXP_LIKE(:NEW.EMP_CODE, '^[0-9A-Za-z][0-9A-Za-z_-]{0,23}$'), FALSE) THEN
    RAISE_APPLICATION_ERROR(-20608, UNISTR('\0631\0642\0645 \0645\0648\0638\0641 \063A\064A\0631 \0635\0627\0644\062D / invalid employee number'));
  END IF;
  :NEW.UPDATED_AT := SYSDATE;
END;
/
CREATE OR REPLACE TRIGGER HDR_BIO_BI BEFORE INSERT ON HDR_BIO FOR EACH ROW
BEGIN
  IF :NEW.BIO_ID IS NULL THEN :NEW.BIO_ID := HDR_SEQ.NEXTVAL; END IF;
END;
/
