END;
/
CREATE OR REPLACE TRIGGER HDR_SCHEDULES_BI BEFORE INSERT ON HDR_SCHEDULES FOR EACH ROW
BEGIN
  IF :NEW.SCHED_ID IS NULL THEN :NEW.SCHED_ID := HDR_SEQ.NEXTVAL; END IF;
END;
/
